  fun ms' => exists m',
          munch (rs_W2 lo sp fb) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
       /\ rw_cells asegs m' fb FBC
       /\ rw_cells asegs m' E (ErrCodeCells E1)
       /\ AHttpCat m' true /\ AXStatics2 m' /\ ACONST m' /\ stack0 m' lo shi
       /\ (   (is_needmore E1 = false /\ rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc lo tot m' ms')
           \/ (is_needmore E1 = true /\ exists jopt rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
                 stk asegs m' lo (bv_unsigned sp + -208)
                 /\ rs_frame m' sp E bs P mw1 mw2 t2c [CB 24 jopt]
                 /\ rw_cells asegs m' (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)
                 /\ ms' = rs_ms RS_DOREAD rax' sp gp tp t0' t1' t2' s0x E a0' a1' a2' a3' a4' a5' a6' a7' tot fb (wz (E + 8)) (wz (E + 16)) s9x t3' t4' t5' t6' F fc m')).
